from typing import TYPE_CHECKING, Annotated, Any, NamedTuple

import torch
from pydantic import BaseModel, PlainSerializer, PlainValidator, WithJsonSchema


if TYPE_CHECKING:
    from typing import TypeVar

    from typing_extensions import TypedDict

    class FileMeta(TypedDict):
        key: str  # parameter name
        dtype: torch.dtype
        shape: torch.Size
        type: type
        tp_concat_dim: int

    T = TypeVar("T")


def _dt_validate(value: Any) -> torch.dtype:
    if isinstance(value, str):
        if not value.startswith("torch."):
            raise ValueError(f"dtype {value} should start with torch.")
        try:
            value = getattr(torch, value.split(".")[1])
        except AttributeError as e:
            raise ValueError(f"unknown dtype: {value}") from e
    if not isinstance(value, torch.dtype):
        raise TypeError(f"dtype {value} should be torch.dtype, got {type(value)}")
    return value


_TorchDtype = Annotated[
    torch.dtype,
    PlainValidator(_dt_validate),
    PlainSerializer(lambda x: str(x), return_type=str),
    WithJsonSchema({"type": "string"}, mode="serialization"),
]


def _size_validate(value: Any) -> torch.Size:
    if isinstance(value, list | tuple):
        return torch.Size(value)
    if not isinstance(value, torch.Size):
        raise TypeError(f"size {value} should be torch.Size, got {type(value)}")
    return value


_TorchSize = Annotated[
    torch.Size,
    PlainValidator(_size_validate),
    PlainSerializer(lambda x: tuple(x), return_type=tuple),
    WithJsonSchema({"type": "array", "items": {"type": "integer"}}, mode="serialization"),
]


def _tensor_validate(value: Any) -> torch.Tensor:
    if isinstance(value, torch.Tensor):
        return value
    raise TypeError(f"tensor {value} should be torch.Tensor, got {type(value)}")


_TorchTensor = Annotated[
    torch.Tensor,
    PlainValidator(_tensor_validate),
]


class ParameterMeta(BaseModel):
    name: str
    dtype: _TorchDtype
    shape: _TorchSize
    aligned_size: int


class BucketRange(NamedTuple):
    idx: int  # bucket_idx of MemoryBucket in memory_pool
    offset: int
    size: int


class H2DBucket(BaseModel):
    size: int
    ranges: list[BucketRange]
    items: list[ParameterMeta]


class MemoryBufferMetas(BaseModel):
    metas: list[ParameterMeta]
    ptr: int
    size: int


class MemoryBuffer(BaseModel):
    buffer: _TorchTensor
    size: int
    metas: list[ParameterMeta]
    manually_pinned: bool = False


class MemoryBufferMetaList(BaseModel):
    p2p_store_addr: str | None
    memory_buffer_metas_list: list[MemoryBufferMetas]
    rdma_device: str


class DataToGather(MemoryBufferMetaList):
    host_ip: str
    device_uuid: str

import importlib
import io
import pickle
from abc import ABC, abstractmethod
from datetime import timedelta
from typing import Any, Protocol

import torch
import torch.distributed as torch_dist


class CommunicatorProtocol(Protocol):
    def all_gather(self, *args: Any, **kwargs: Any) -> torch.Tensor: ...


class CommGroup:
    def __init__(self, comm_handle: int, ranks: list[int]):
        self._comm = comm_handle
        self._ranks = ranks

    @property
    def handle(self) -> int:
        return self._comm

    @property
    def ranks(self) -> list[int]:
        return self._ranks


DistributedProcessGroup = torch_dist.ProcessGroup | CommGroup


class Distributed(ABC):
    @abstractmethod
    def init_process_group(
        self,
        rank: int,
        world_size: int,
        store: torch_dist.TCPStore,
        **kwargs,
    ):
        raise NotImplementedError

    @abstractmethod
    def destroy_process_group(
        self,
        group: DistributedProcessGroup | None = None,
    ):
        raise NotImplementedError

    @abstractmethod
    def is_initialized(self) -> bool:
        raise NotImplementedError

    @abstractmethod
    def all_gather_object(
        self,
        object_list: list[Any],
        obj: Any,
        group: DistributedProcessGroup | None = None,
    ):
        raise NotImplementedError

    @abstractmethod
    def all_reduce(
        self,
        tensor: torch.Tensor,
        op: torch_dist.ReduceOp.RedOpType,
        group: DistributedProcessGroup | None = None,
        **kwargs,
    ):
        raise NotImplementedError

    @abstractmethod
    def broadcast(
        self,
        tensor: torch.Tensor,
        src: int,
        group: DistributedProcessGroup | None = None,
        **kwargs,
    ):
        raise NotImplementedError

    @abstractmethod
    def barrier(
        self,
        group: DistributedProcessGroup | None = None,
        **kwargs,
    ):
        raise NotImplementedError

    @abstractmethod
    def new_group(
        self,
        ranks: list[int],
        **kwargs,
    ):
        raise NotImplementedError


class TorchBackend(Distributed):
    def init_process_group(
        self,
        rank: int,
        world_size: int,
        store: torch_dist.TCPStore,
        **kwargs,
    ):
        backend = kwargs.get("backend", "nccl")
        timeout = kwargs.get("timeout", timedelta(minutes=10))

        torch_dist.init_process_group(
            backend=backend,
            world_size=world_size,
            rank=rank,
            timeout=timeout,
            store=store,
        )

    def destroy_process_group(self, group: DistributedProcessGroup | None = None):
        torch_dist.destroy_process_group(group)

    def is_initialized(self) -> bool:
        return torch_dist.is_initialized()

    def all_gather_object(
        self, object_list: list[Any], obj: Any, group: DistributedProcessGroup | None = None
    ):
        torch_dist.all_gather_object(object_list, obj, group)

    def all_reduce(
        self,
        tensor: torch.Tensor,
        op: torch_dist.ReduceOp.RedOpType = torch_dist.ReduceOp.SUM,
        group: DistributedProcessGroup | None = None,
        **kwargs,
    ):
        torch_dist.all_reduce(tensor, op, group, **kwargs)

    def broadcast(
        self,
        tensor: torch.Tensor,
        src: int = 0,
        group: DistributedProcessGroup | None = None,
        **kwargs,
    ):
        torch_dist.broadcast(tensor, src, group, **kwargs)

    def barrier(self, group: DistributedProcessGroup | None = None, **kwargs):
        torch_dist.barrier(group, **kwargs)

    def new_group(self, ranks: list[int], **kwargs) -> DistributedProcessGroup | None:
        return torch_dist.new_group(ranks, **kwargs)


# specific device instance
_BACKEND_INSTANCE: Distributed = TorchBackend()

_pickler = pickle.Pickler
_unpickler = pickle.Unpickler


def _object_to_tensor(obj: Any, device: torch.device) -> tuple[torch.Tensor, torch.Tensor]:
    f = io.BytesIO()
    _pickler(f).dump(obj)
    byte_storage = torch.ByteStorage._from_buffer(f.getvalue())
    byte_tensor = torch.ByteTensor(byte_storage).to(device)
    local_size = torch.LongTensor([byte_tensor.numel()]).to(device)
    return byte_tensor, local_size


def _tensor_to_object(tensor: torch.Tensor, tensor_size: int) -> Any:
    tensor = tensor.cpu()
    buf = tensor.numpy().tobytes()[:tensor_size]
    return _unpickler(io.BytesIO(buf)).load()


def _flatten_for_scatter_gather(
    tensor_list: list[torch.Tensor], copy: bool = False
) -> torch.Tensor:
    if not tensor_list:
        raise RuntimeError("Received an empty list.")
    t = tensor_list[0]
    buffer_shape = [len(tensor_list)] + list(t.shape)

    buffer = torch.empty(tuple(buffer_shape), dtype=t.dtype, device=t.device)
    if copy:
        for i, tensor in enumerate(tensor_list):
            buffer[i].copy_(tensor)
    return buffer


def _common_all_gather_object(
    comm: CommunicatorProtocol,
    device: torch.device,
    world_size: int,
    object_list: list[Any],
    object: Any,
):
    input_tensor, local_size = _object_to_tensor(object, device)
    object_sizes_tensor = torch.empty(world_size, dtype=torch.long, device=device)
    comm.all_gather(object_sizes_tensor, local_size)
    object_size_list = [object_sizes_tensor[i].unsqueeze(dim=0) for i in range(world_size)]
    max_object_size = int(max(object_size_list).item())
    input_tensor.resize_(max_object_size)
    coalesced_output_tensor = torch.empty(
        max_object_size * world_size, dtype=torch.uint8, device=device
    )

    comm.all_gather(coalesced_output_tensor, input_tensor)
    output_tensors = [
        coalesced_output_tensor[max_object_size * i : max_object_size * (i + 1)]
        for i in range(world_size)
    ]
    for i, tensor in enumerate(output_tensors):
        tensor = tensor.type(torch.uint8)
        tensor_size = object_size_list[i]
        object_list[i] = _tensor_to_object(tensor, tensor_size)


def use_backend(backend: str | None):
    global _BACKEND_INSTANCE

    if not backend:
        return

    mapping = {
        "vllm_nccl": ".vllm_nccl.DistributedNccl",
        "vllm_hccl": ".vllm_hccl.DistributedHccl",
    }
    if backend not in mapping:
        # XPU has no custom backend; leave custom_dist unset to use the default xccl TorchBackend.
        raise ValueError(
            f"Unsupported custom backend: {backend}. "
            f"Supported custom backends: {sorted(mapping)}. "
            "XPU is not supported here; leave custom_dist unset to use the default xccl backend."
        )

    module_path, class_name = mapping[backend].rsplit(".", 1)
    module = importlib.import_module(module_path, "checkpoint_engine.distributed")
    backend_class = getattr(module, class_name)
    _BACKEND_INSTANCE = backend_class()


def init_process_group(
    rank: int,
    world_size: int,
    store: torch_dist.TCPStore,
    **kwargs,
):
    _BACKEND_INSTANCE.init_process_group(rank, world_size, store, **kwargs)


def destroy_process_group(group: DistributedProcessGroup | None = None):
    _BACKEND_INSTANCE.destroy_process_group(group)


def is_initialized() -> bool:
    return _BACKEND_INSTANCE.is_initialized()


def all_gather_object(
    object_list: list[Any],
    obj: Any,
    group: DistributedProcessGroup | None = None,
):
    _BACKEND_INSTANCE.all_gather_object(object_list, obj, group)


def all_reduce(
    tensor: torch.Tensor,
    op: torch_dist.ReduceOp.RedOpType = torch_dist.ReduceOp.SUM,
    group: DistributedProcessGroup | None = None,
    **kwargs,
):
    _BACKEND_INSTANCE.all_reduce(tensor, op, group, **kwargs)


def broadcast(
    tensor: torch.Tensor,
    src: int = 0,
    group: DistributedProcessGroup | None = None,
    **kwargs,
):
    _BACKEND_INSTANCE.broadcast(tensor, src, group, **kwargs)


def barrier(group: DistributedProcessGroup | None = None, **kwargs):
    _BACKEND_INSTANCE.barrier(group, **kwargs)


def new_group(ranks: list[int], **kwargs) -> DistributedProcessGroup | None:
    return _BACKEND_INSTANCE.new_group(ranks, **kwargs)

from collections.abc import Callable
from typing import Any

import fastapi
import httpx
from fastapi import HTTPException, Request
from fastapi.responses import JSONResponse, Response
from loguru import logger
from pydantic import BaseModel

from checkpoint_engine.data_types import MemoryBufferMetaList
from checkpoint_engine.ps import ParameterServer


def request_inference_to_update(
    url: str,
    socket_paths: dict[str, str],
    timeout: float = 300.0,
    uds: str | None = None,
):
    """Send an inference update request to inference server via HTTP or Unix socket.

    Args:
        url (str): The HTTP URL or request path (e.g., "http://localhost:19730/inference") to send the request to.
        socket_paths (dict[str, str]): A dictionary containing device uuid and IPC socket paths for updating weights.
        timeout (float, optional): Request timeout in seconds. Defaults to 300.0.
        uds (str, optional): Path to a Unix domain socket. If provided, the request
            will be sent via the Unix socket instead of HTTP. Defaults to None.

    Raises:
        httpx.HTTPStatusError: If the response contains an HTTP error status.
        httpx.RequestError: If there was an issue while making the request.
    """
    resp = httpx.Client(transport=httpx.HTTPTransport(uds=uds)).post(
        url,
        json={
            "method": "update_weights_from_ipc",
            "args": [socket_paths],
            "timeout": timeout,
        },
        timeout=timeout,
    )
    resp.raise_for_status()


def _init_api(ps: ParameterServer) -> Any:
    app = fastapi.FastAPI()

    class RegisterRequest(BaseModel):
        files: list[str]

    class UpdateRequest(BaseModel):
        ranks: list[int] = []
        update_url: str | None = None
        inference_group_ranks: list[int] = []
        timeout: float = 300.0
        uds: str | None = None

    def wrap_exception(func: Callable[[], None]) -> Response:
        try:
            func()
        except Exception as e:  # noqa: BLE001
            logger.exception(f"wrap exception {func} failed")
            return JSONResponse(content=str(e), status_code=500)
        return Response(status_code=200)

    @app.post("/v1/checkpoints/{checkpoint_name}/files")
    async def register_files(checkpoint_name: str, req: RegisterRequest, raw: Request) -> Response:
        return wrap_exception(lambda: ps.register_checkpoint(checkpoint_name, files=req.files))

    @app.delete("/v1/checkpoints/{checkpoint_name}")
    async def unregister_checkpoint(checkpoint_name: str) -> Response:
        return wrap_exception(lambda: ps.unregister_checkpoint(checkpoint_name))

    @app.get("/v1/healthz")
    async def healthz() -> Response:
        return Response(status_code=200)

    @app.post("/v1/checkpoints/{checkpoint_name}/gather-metas")
    async def gather_metas(checkpoint_name: str) -> Response:
        return wrap_exception(lambda: ps.gather_metas(checkpoint_name))

    @app.get("/v1/metas")
    async def get_metas() -> dict[int, MemoryBufferMetaList]:
        try:
            return ps.get_metas()
        except Exception as e:
            logger.exception("get_metas failed")
            raise HTTPException(status_code=500, detail=str(e)) from e

    @app.post("/v1/metas")
    async def load_metas(metas: dict[int, MemoryBufferMetaList]) -> Response:
        return wrap_exception(lambda: ps.load_metas(metas))

    @app.post("/v1/checkpoints/{checkpoint_name}/update")
    async def update(checkpoint_name: str, req: UpdateRequest) -> Response:
        def update_func(socket_paths: list[tuple[str, str]]):
            if req.update_url is None:
                return
            if req.inference_group_ranks:
                socket_paths = [socket_paths[i] for i in req.inference_group_ranks]
            request_inference_to_update(
                req.update_url, dict(socket_paths), timeout=req.timeout, uds=req.uds
            )

        return wrap_exception(lambda: ps.update(checkpoint_name, update_func, ranks=req.ranks))

    return app

